import fs from 'node:fs';import {createHash} from 'node:crypto';
const stage='tmp/bettiah-walking-fix-20261008';
const probe=JSON.parse(fs.readFileSync(stage+'/head-probe.json','utf8'));
if(probe.dimensions!==512||probe.weights.length!==512||!probe.weights.every(Number.isFinite)||!Number.isFinite(probe.bias))throw Error('Invalid classifier');
for(const split of ['train','test'])if(probe.summary[split].falsePositivesAt080||probe.summary[split].missedPositivesAt080)throw Error('Classifier regression failed');
if(probe.summary.bettiahFeedback.minPositive<.9)throw Error('Missed pose remains below strong evidence gate');
const modelHash=createHash('sha256').update(fs.readFileSync('analytics-engine/models/safety/helmet-head-embedding.onnx')).digest('hex');
if(modelHash!==probe.featureModelSha256)throw Error('Feature model changed');
const parameters={dimensions:512,weights:probe.weights,bias:probe.bias};
const hash=createHash('sha256').update(JSON.stringify(parameters)).digest('hex');
fs.writeFileSync(stage+'/analytics-engine/src/inference/helmet-head-probe.ts',
 '// Generated by scratch/package-bettiah-walking-probe-20261008.mjs.\n'+
 '// Frozen features; confirmed Bettiah pose is training feedback, separate from held-out regression.\n'+
 'export const HELMET_HEAD_PROBE_SHA256 = '+JSON.stringify(hash)+';\n'+
 'export const HELMET_HEAD_PROBE = '+JSON.stringify(parameters)+' as const;\n');
const detector=stage+'/analytics-engine/src/detectors/helmet-detector.ts';
let code=fs.readFileSync(detector,'utf8');if(!code.includes('super("helmet", "1.3.2")'))throw Error('Unexpected detector');
fs.writeFileSync(detector,code.replace('super("helmet", "1.3.2")','super("helmet", "1.3.3")'));
let replay=fs.readFileSync(stage+'/scratch/replay-bettiah.ts','utf8');
fs.writeFileSync(stage+'/scratch/replay-bettiah.ts',replay);
replay=fs.readFileSync(stage+'/scratch/replay-presentation.ts','utf8').replace('presentation-native-retry-replay-2026-10-08.json','bettiah-walking-independent-replay-2026-10-08.json');
fs.writeFileSync(stage+'/scratch/replay-presentation.ts',replay);
console.log(JSON.stringify({probeSha256:hash,version:'1.3.3',featureModelSha256:modelHash,summary:probe.summary},null,2));
